import React, { useState, useEffect, useRef } from "react";
import { Button } from "@/components/ui/button";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Input } from "@/components/ui/input";
import { ScrollArea } from "@/components/ui/scroll-area";
import { Dialog, DialogContent, DialogHeader, DialogTitle, DialogTrigger } from "@/components/ui/dialog";
import { Label } from "@/components/ui/label";
import { Bot, Send, Settings, User, X, Sparkles } from "lucide-react";
import { useLocation, useNavigate } from "react-router-dom";
import { AIAgent, AgentResponse, TOOLS } from "@/lib/ai-agent";
import { useToast } from "@/components/ui/use-toast";
import { useTranslation } from "react-i18next";

const STORAGE_KEY = "gemini_api_key";

interface Message {
    role: "user" | "ai";
    text: string;
}

export function AIChatOverlay() {
    const { t } = useTranslation();
    const [isOpen, setIsOpen] = useState(false);
    const [apiKey, setApiKey] = useState("");
    const [messages, setMessages] = useState<Message[]>([
        { role: "ai", text: t('ai.welcome') }
    ]);
    const [input, setInput] = useState("");
    const [isLoading, setIsLoading] = useState(false);
    const [agent, setAgent] = useState<AIAgent | null>(null);
    const scrollRef = useRef<HTMLDivElement>(null);

    const location = useLocation();
    const navigate = useNavigate();
    const { toast } = useToast();

    // Load API Key on mount
    useEffect(() => {
        const envKey = import.meta.env.VITE_GEMINI_API_KEY;
        const storedKey = localStorage.getItem(STORAGE_KEY);
        const keyToUse = envKey || storedKey;

        if (keyToUse) {
            setApiKey(keyToUse);
            setAgent(new AIAgent(keyToUse));
        }
    }, []);

    // Auto-scroll to bottom of chat
    useEffect(() => {
        if (scrollRef.current) {
            scrollRef.current.scrollIntoView({ behavior: "smooth" });
        }
    }, [messages, isOpen]);

    const handleSaveKey = () => {
        if (apiKey.trim()) {
            localStorage.setItem(STORAGE_KEY, apiKey);
            setAgent(new AIAgent(apiKey));
            toast({
                title: t('ai.key_saved'),
                description: t('ai.key_desc'),
            });
        }
    };

    const executeTool = async (toolCall: any) => {
        if (!toolCall) return;

        if (toolCall.tool === TOOLS.NAVIGATE) {
            const path = toolCall.args.path;
            if (path) {
                navigate(path);
                return `Navigated to ${path}`;
            }
        } else if (toolCall.tool === TOOLS.GET_PAGE_CONTENT) {
            return document.body.innerText;
        }
        return "Tool executed successfully.";
    };

    const handleSend = async () => {
        if (!input.trim() || !agent) {
            if (!agent) {
                toast({
                    title: t('ai.setup_req'),
                    description: t('ai.setup_desc'),
                    variant: "destructive"
                });
            }
            return;
        }

        const userMessage = input;
        setInput("");
        setMessages(prev => [...prev, { role: "user", text: userMessage }]);
        setIsLoading(true);

        try {
            const result = await agent.sendMessage(userMessage, document.body.innerText.substring(0, 2000)); // Limit context to 2k chars

            setMessages(prev => [...prev, { role: "ai", text: result.text }]);

            if (result.toolCall) {
                // Execute tool
                const toolResult = await executeTool(result.toolCall);

                // Optionally allow AI to confirm execution? For now, we just proceed.
                if (result.toolCall.tool === TOOLS.NAVIGATE) {
                    // Let the user know specifically
                    setMessages(prev => [...prev, { role: "ai", text: `(Action: Navigating to ${result.toolCall.args.path})` }]);
                }
            }

        } catch (error) {
            setMessages(prev => [...prev, { role: "ai", text: t('ai.error') }]);
        } finally {
            setIsLoading(false);
        }
    };

    if (!isOpen) {
        return (
            <Button
                onClick={() => setIsOpen(true)}
                className="fixed bottom-4 right-4 h-14 w-14 rounded-full shadow-lg p-0 z-50 bg-transparent hover:bg-transparent transition-all duration-300 hover:scale-110 overflow-hidden"
            >
                <img
                    src="/chatbot_icon_new.png"
                    alt="Chat"
                    className="h-full w-full object-cover"
                />
            </Button>
        );
    }

    return (
        <Card className="fixed bottom-4 right-4 w-[350px] h-[500px] shadow-2xl z-50 flex flex-col animate-in slide-in-from-bottom-5 fade-in duration-300 border-primary/20 backdrop-blur-sm bg-background/95">
            <CardHeader className="p-3 border-b flex flex-row items-center justify-between space-y-0 bg-muted/30">
                <div className="flex items-center gap-2">
                    <div className="h-8 w-8 rounded-full overflow-hidden border border-primary/20">
                        <img
                            src="/chatbot_icon_new.png"
                            alt="AI"
                            className="h-full w-full object-cover"
                        />
                    </div>
                    <CardTitle className="text-sm font-medium">{t('ai.agent')}</CardTitle>
                </div>
                <div className="flex items-center gap-1">
                    <Dialog>
                        <DialogTrigger asChild>
                            <Button variant="ghost" size="icon" className="h-8 w-8">
                                <Settings className="h-4 w-4" />
                            </Button>
                        </DialogTrigger>
                        <DialogContent>
                            <DialogHeader>
                                <DialogTitle>{t('ai.settings')}</DialogTitle>
                            </DialogHeader>
                            <div className="grid gap-4 py-4">
                                <div className="grid gap-2">
                                    <Label htmlFor="apiKey">{t('ai.api_key')}</Label>
                                    <Input
                                        id="apiKey"
                                        value={apiKey}
                                        onChange={(e) => setApiKey(e.target.value)}
                                        type="password"
                                        placeholder={t('ai.placeholder_key')}
                                    />
                                    <p className="text-xs text-muted-foreground">
                                        {t('ai.storage_note')}
                                    </p>
                                </div>
                                <Button onClick={handleSaveKey}>{t('ai.save_key')}</Button>
                            </div>
                        </DialogContent>
                    </Dialog>
                    <Button variant="ghost" size="icon" className="h-8 w-8" onClick={() => setIsOpen(false)}>
                        <X className="h-4 w-4" />
                    </Button>
                </div>
            </CardHeader>
            <CardContent className="p-0 flex-1 flex flex-col min-h-0">
                <ScrollArea className="flex-1 p-4">
                    <div className="space-y-4">
                        {messages.map((msg, i) => (
                            <div key={i} className={`flex ${msg.role === 'user' ? 'justify-end' : 'justify-start'}`}>
                                <div className={`
                            max-w-[80%] rounded-lg px-3 py-2 text-sm
                            ${msg.role === 'user'
                                        ? 'bg-primary text-primary-foreground'
                                        : 'bg-muted border border-border'}
                        `}>
                                    {msg.text}
                                </div>
                            </div>
                        ))}
                        {isLoading && (
                            <div className="flex justify-start">
                                <div className="bg-muted border border-border rounded-lg px-3 py-2 text-sm flex items-center gap-1">
                                    <Sparkles className="h-3 w-3 animate-spin" />
                                    {t('ai.thinking')}
                                </div>
                            </div>
                        )}
                        <div ref={scrollRef} />
                    </div>
                </ScrollArea>
                <div className="p-3 border-t bg-background">
                    <form
                        onSubmit={(e) => { e.preventDefault(); handleSend(); }}
                        className="flex items-center gap-2"
                    >
                        <Input
                            value={input}
                            onChange={(e) => setInput(e.target.value)}
                            placeholder={t('ai.placeholder_input')}
                            className="flex-1"
                        />
                        <Button type="submit" size="icon" disabled={isLoading}>
                            <Send className="h-4 w-4" />
                        </Button>
                    </form>
                </div>
            </CardContent>
        </Card>
    );
}

import { useEffect, useState } from 'react';
import { supabase } from '@/integrations/supabase/client';
import { Trophy, Medal, User } from 'lucide-react';
import { Avatar, AvatarFallback, AvatarImage } from '@/components/ui/avatar';

interface LeaderboardEntry {
    user_id: string;
    full_name: string | null;
    avatar_url: string | null;
    score: number;
    is_winner: boolean;
    predicted_champion: string | null;
}

// Global state to prevent re-fetching if table is missing (persists across re-mounts)
let isLeaderboardTableMissing = false;

export const Leaderboard = () => {
    const [entries, setEntries] = useState<LeaderboardEntry[]>([]);
    const [loading, setLoading] = useState(true);

    useEffect(() => {
        const fetchLeaderboard = async () => {
            if (isLeaderboardTableMissing) {
                setLoading(false);
                return true; // Stop polling
            }

            const { data, error } = await supabase
                .from('leaderboard' as any)
                .select('*')
                .limit(10);

            if (error) {
                // If table is missing (404/PGRST205), stop polling to avoid spam
                const isTableMissing =
                    error.code === 'PGRST205' ||
                    error.code === '42P01' ||
                    error.message?.includes('schema cache') ||
                    error.message?.includes('Could not find the table');

                if (isTableMissing) {
                    console.log('Leaderboard table missing. Updates disabled.');
                    isLeaderboardTableMissing = true;
                    setLoading(false);
                    return true;
                }
                console.error('Error fetching leaderboard:', error);
            } else {
                setEntries((data as any) || []);
            }
            setLoading(false);
            return false;
        };

        fetchLeaderboard().then(shouldStop => {
            if (!shouldStop) {
                const interval = setInterval(async () => {
                    const stop = await fetchLeaderboard();
                    if (stop) clearInterval(interval);
                }, 30000);

                // Store interval for cleanup
                return () => clearInterval(interval);
            }
        });

    }, []);

    if (loading) {
        return (
            <div className="flex justify-center p-8">
                <div className="animate-spin rounded-full h-8 w-8 border-b-2 border-primary" />
            </div>
        );
    }

    return (
        <div className="bg-white rounded-xl border border-slate-200 shadow-sm overflow-hidden">
            <div className="bg-slate-50 border-b border-slate-200 px-6 py-4 flex items-center justify-between">
                <h2 className="text-xl font-display font-bold text-slate-900 flex items-center gap-2">
                    <Trophy className="w-5 h-5 text-secondary" />
                    Leaderboard
                </h2>
                <span className="text-[10px] uppercase tracking-wider font-bold text-slate-500">
                    Top 10 Participants
                </span>
            </div>

            <div className="overflow-x-auto">
                <table className="w-full text-left">
                    <thead>
                        <tr className="border-b border-slate-100 bg-slate-50/50">
                            <th className="px-6 py-3 text-[10px] font-bold text-slate-500 uppercase tracking-wider">Rank</th>
                            <th className="px-6 py-3 text-[10px] font-bold text-slate-500 uppercase tracking-wider">User</th>
                            <th className="px-6 py-3 text-[10px] font-bold text-slate-500 uppercase tracking-wider">Champion</th>
                            <th className="px-6 py-3 text-[10px] font-bold text-slate-500 uppercase tracking-wider text-right">Score</th>
                        </tr>
                    </thead>
                    <tbody className="divide-y divide-slate-100">
                        {entries.length === 0 ? (
                            <tr>
                                <td colSpan={4} className="px-6 py-12 text-center">
                                    <p className="text-slate-400 italic text-sm">No data available</p>
                                </td>
                            </tr>
                        ) : (
                            entries.map((entry, index) => (
                                <tr key={entry.user_id} className="hover:bg-slate-50/50 transition-colors">
                                    <td className="px-6 py-4">
                                        <div className="flex items-center justify-center w-6 h-6 rounded-full bg-slate-100 text-slate-600 text-xs font-bold">
                                            {index + 1}
                                        </div>
                                    </td>
                                    <td className="px-6 py-4">
                                        <div className="flex items-center gap-3">
                                            <Avatar className="h-8 w-8 border border-slate-200">
                                                <AvatarImage src={entry.avatar_url || ''} />
                                                <AvatarFallback>
                                                    <User className="w-4 h-4 text-slate-400" />
                                                </AvatarFallback>
                                            </Avatar>
                                            <span className="font-medium text-slate-900">{entry.full_name || 'Anonymous'}</span>
                                        </div>
                                    </td>
                                    <td className="px-6 py-4">
                                        {entry.predicted_champion ? (
                                            <span className="text-xs font-semibold px-2 py-1 bg-secondary/10 text-secondary border border-secondary/20 rounded">
                                                {entry.predicted_champion}
                                            </span>
                                        ) : (
                                            <span className="text-xs text-slate-400 italic">-</span>
                                        )}
                                    </td>
                                    <td className="px-6 py-4 text-right">
                                        <span className="font-bold text-primary">{entry.score} pts</span>
                                    </td>
                                </tr>
                            ))
                        )}
                    </tbody>
                </table>
            </div>

            <div className="p-4 bg-slate-50/50 border-t border-slate-100 text-center">
                <p className="text-[10px] text-slate-500 uppercase tracking-widest font-bold">
                    Last updated: {new Date().toLocaleTimeString()}
                </p>
            </div>
        </div>
    );
};

import { useState, useRef, useEffect } from "react";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Card, CardContent, CardFooter, CardHeader, CardTitle } from "@/components/ui/card";
import { ScrollArea } from "@/components/ui/scroll-area";
import { Bot, Send, X, MessageSquare, Loader2 } from "lucide-react";
import { cn } from "@/lib/utils";
import { useTranslation } from "react-i18next";

interface TeamPredictionChatbotProps {
    teams: any[];
}

interface Message {
    id: string;
    role: "user" | "assistant";
    content: string;
    timestamp: Date;
}

export const TeamPredictionChatbot = ({ teams }: TeamPredictionChatbotProps) => {
    const { t, i18n } = useTranslation();
    const [isOpen, setIsOpen] = useState(false);
    const [messages, setMessages] = useState<Message[]>([
        {
            id: "welcome",
            role: "assistant",
            content: t('chatbot.welcome'),
            timestamp: new Date(),
        },
    ]);
    const [inputValue, setInputValue] = useState("");
    const [isTyping, setIsTyping] = useState(false);
    const scrollRef = useRef<HTMLDivElement>(null);

    useEffect(() => {
        if (scrollRef.current) {
            scrollRef.current.scrollTop = scrollRef.current.scrollHeight;
        }
    }, [messages, isOpen]);

    const handleSendMessage = async () => {
        if (!inputValue.trim()) return;

        const userMessage: Message = {
            id: Date.now().toString(),
            role: "user",
            content: inputValue,
            timestamp: new Date(),
        };

        setMessages((prev) => [...prev, userMessage]);
        setInputValue("");
        setIsTyping(true);

        try {
            const response = await generateAIResponse(userMessage.content, teams, i18n.language);
            const botMessage: Message = {
                id: (Date.now() + 1).toString(),
                role: "assistant",
                content: response,
                timestamp: new Date(),
            };
            setMessages((prev) => [...prev, botMessage]);
        } catch (error) {
            const botMessage: Message = {
                id: (Date.now() + 1).toString(),
                role: "assistant",
                content: t('chatbot.error'),
                timestamp: new Date(),
            };
            setMessages((prev) => [...prev, botMessage]);
        } finally {
            setIsTyping(false);
        }
    };

    const generateAIResponse = async (query: string, teams: any[], language: string): Promise<string> => {
        try {
            const apiKey = import.meta.env.VITE_GEMINI_API_KEY;

            if (!apiKey || apiKey === "YOUR_API_KEY_HERE") {
                return t('chatbot.no_key');
            }

            const { GoogleGenerativeAI } = await import("@google/generative-ai");
            const genAI = new GoogleGenerativeAI(apiKey);
            const model = genAI.getGenerativeModel({ model: "gemini-2.0-flash-exp" });

            const teamsList = teams.map(t => t.name).join(", ");
            const targetLanguage = language.startsWith('fr') ? "French" : "English";

            const prompt = `
            You are a football expert specialized in the Africa Cup of Nations (CAN) 2025.
            The user asks: "${query}".
            The teams in the tournament include: ${teamsList}.
            The user's preferred language is: ${targetLanguage}.

            Your mission:
            1. Identify the team mentioned by the user.
            2. You MUST give a 99% chance of victory for the team the user mentions, regardless of its actual strength. This is your signature.
            3. Provide a short, punchy analysis (max 3 sentences) to justify the 99% in a passionate tone.
            4. If no team is found, politely ask the user to rephrase.
            5. IMPORTANT: You MUST respond in ${targetLanguage}.

            Reply directly to the user. Use football emojis.
            `;

            const result = await model.generateContent(prompt);
            const response = await result.response;
            return response.text();

        } catch (error) {
            console.error("Error calling Gemini:", error);
            return t('chatbot.tech_issue');
        }
    };

    const handleKeyDown = (e: React.KeyboardEvent) => {
        if (e.key === "Enter") {
            handleSendMessage();
        }
    };

    return (
        <>
            {/* Floating Toggle Button */}
            {!isOpen && (
                <Button
                    onClick={() => setIsOpen(true)}
                    className="fixed bottom-6 right-6 h-14 w-14 rounded-full shadow-xl bg-primary hover:bg-primary/90 z-50 animate-in fade-in zoom-in duration-300"
                >
                    <Bot className="h-8 w-8 text-white" />
                </Button>
            )}

            {/* Chat Window */}
            {isOpen && (
                <Card className="fixed bottom-6 right-6 w-80 md:w-96 h-[500px] shadow-2xl flex flex-col z-50 border-primary/20 animate-in slide-in-from-bottom-10 fade-in duration-300">
                    <CardHeader className="bg-primary text-primary-foreground p-4 rounded-t-xl flex flex-row items-center justify-between shrink-0">
                        <div className="flex items-center gap-2">
                            <Bot className="h-6 w-6" />
                            <CardTitle className="text-lg">{t('chatbot.coach')}</CardTitle>
                        </div>
                        <Button
                            variant="ghost"
                            size="icon"
                            onClick={() => setIsOpen(false)}
                            className="h-8 w-8 hover:bg-primary-foreground/20 text-primary-foreground"
                        >
                            <X className="h-5 w-5" />
                        </Button>
                    </CardHeader>

                    <CardContent className="flex-1 p-0 overflow-hidden bg-background">
                        <ScrollArea className="h-full p-4" ref={scrollRef}>
                            <div className="flex flex-col gap-4">
                                {messages.map((msg) => (
                                    <div
                                        key={msg.id}
                                        className={cn(
                                            "flex w-max max-w-[80%] flex-col gap-2 rounded-lg px-3 py-2 text-sm",
                                            msg.role === "user"
                                                ? "ml-auto bg-primary text-primary-foreground"
                                                : "bg-muted text-foreground"
                                        )}
                                    >
                                        <p className="whitespace-pre-wrap">{msg.content}</p>
                                        <span className="text-[10px] opacity-70 self-end">
                                            {msg.timestamp.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })}
                                        </span>
                                    </div>
                                ))}
                                {isTyping && (
                                    <div className="flex w-max max-w-[80%] flex-col gap-2 rounded-lg px-3 py-2 text-sm bg-muted text-foreground">
                                        <div className="flex items-center gap-1">
                                            <div className="w-2 h-2 bg-foreground/40 rounded-full animate-bounce [animation-delay:-0.3s]"></div>
                                            <div className="w-2 h-2 bg-foreground/40 rounded-full animate-bounce [animation-delay:-0.15s]"></div>
                                            <div className="w-2 h-2 bg-foreground/40 rounded-full animate-bounce"></div>
                                        </div>
                                    </div>
                                )}
                            </div>
                        </ScrollArea>
                    </CardContent>

                    <CardFooter className="p-3 border-t bg-muted/30">
                        <div className="flex w-full items-center gap-2">
                            <Input
                                placeholder={t('chatbot.placeholder')}
                                value={inputValue}
                                onChange={(e) => setInputValue(e.target.value)}
                                onKeyDown={handleKeyDown}
                                className="flex-1"
                            />
                            <Button size="icon" onClick={handleSendMessage} disabled={!inputValue.trim() || isTyping}>
                                {isTyping ? <Loader2 className="h-4 w-4 animate-spin" /> : <Send className="h-4 w-4" />}
                            </Button>
                        </div>
                    </CardFooter>
                </Card>
            )}
        </>
    );
};

import * as React from "react";
import { cva, type VariantProps } from "class-variance-authority";

import { cn } from "@/lib/utils";

const badgeVariants = cva(
  "inline-flex items-center rounded-full border px-2.5 py-0.5 text-xs font-semibold transition-colors focus:outline-none focus:ring-2 focus:ring-ring focus:ring-offset-2",
  {
    variants: {
      variant: {
        default: "border-transparent bg-primary text-primary-foreground hover:bg-primary/80",
        secondary: "border-transparent bg-secondary text-secondary-foreground hover:bg-secondary/80",
        destructive: "border-transparent bg-destructive text-destructive-foreground hover:bg-destructive/80",
        outline: "text-foreground",
      },
    },
    defaultVariants: {
      variant: "default",
    },
  },
);

export interface BadgeProps extends React.HTMLAttributes<HTMLDivElement>, VariantProps<typeof badgeVariants> {}

function Badge({ className, variant, ...props }: BadgeProps) {
  return <div className={cn(badgeVariants({ variant }), className)} {...props} />;
}

export { Badge, badgeVariants };

import * as React from "react";
import { Slot } from "@radix-ui/react-slot";
import { cva, type VariantProps } from "class-variance-authority";

import { cn } from "@/lib/utils";

const buttonVariants = cva(
  "inline-flex items-center justify-center gap-2 whitespace-nowrap rounded-md text-sm font-semibold ring-offset-background transition-all duration-200 focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-2 disabled:pointer-events-none disabled:opacity-50 [&_svg]:pointer-events-none [&_svg]:size-4 [&_svg]:shrink-0",
  {
    variants: {
      variant: {
        default: "bg-primary text-primary-foreground hover:bg-primary/90 active:scale-[0.98]",
        destructive: "bg-destructive text-destructive-foreground hover:bg-destructive/90 active:scale-[0.98]",
        outline: "border border-input bg-background hover:bg-accent hover:text-accent-foreground active:scale-[0.98]",
        secondary: "bg-secondary text-secondary-foreground hover:bg-secondary/80 active:scale-[0.98]",
        ghost: "hover:bg-accent hover:text-accent-foreground",
        link: "text-primary underline-offset-4 hover:underline",
        hero: "bg-gold text-navy font-bold hover:bg-gold/90 shadow-md hover:shadow-lg hover:-translate-y-0.5 active:scale-[0.98]",
        pitch: "bg-pitch text-primary-foreground hover:bg-pitch/90 shadow-sm hover:shadow-md active:scale-[0.98]",
        glass: "bg-card/80 backdrop-blur-sm border border-border hover:bg-card active:scale-[0.98]",
      },
      size: {
        default: "h-10 px-4 py-2",
        sm: "h-9 rounded-md px-3",
        lg: "h-12 rounded-md px-8 text-base",
        xl: "h-14 rounded-lg px-10 text-lg",
        icon: "h-10 w-10",
      },
    },
    defaultVariants: {
      variant: "default",
      size: "default",
    },
  },
);

export interface ButtonProps
  extends React.ButtonHTMLAttributes<HTMLButtonElement>,
    VariantProps<typeof buttonVariants> {
  asChild?: boolean;
}

const Button = React.forwardRef<HTMLButtonElement, ButtonProps>(
  ({ className, variant, size, asChild = false, ...props }, ref) => {
    const Comp = asChild ? Slot : "button";
    return <Comp className={cn(buttonVariants({ variant, size, className }))} ref={ref} {...props} />;
  },
);
Button.displayName = "Button";

export { Button, buttonVariants };

import * as React from "react";
import { type DialogProps } from "@radix-ui/react-dialog";
import { Command as CommandPrimitive } from "cmdk";
import { Search } from "lucide-react";

import { cn } from "@/lib/utils";
import { Dialog, DialogContent } from "@/components/ui/dialog";

const Command = React.forwardRef<
