  const activeUserName = user ? (profile?.full_name || user.email?.split('@')[0] || "Anonymous") : localUserName;

  // Fetch posts
  const { data: posts, isLoading, error: queryError } = useQuery({
    queryKey: ["chat_posts"],
    queryFn: async () => {
      if (!isSupabaseConfigured) return [];
      const { data, error } = await supabase
        .from("chat_posts")
        .select("*, chat_comments(*)")
        .order("created_at", { ascending: false });
      if (error) throw error;
      return (data || []).map((post: any) => ({
        ...post,
        chat_comments: (post.chat_comments || []).sort((a: any, b: any) =>
          new Date(a.created_at).getTime() - new Date(b.created_at).getTime()
        )
      })) as Post[];
    },
    retry: 1,
  });

  const displayPosts = queryError || (!isLoading && (!posts || posts.length === 0))
    ? [...localPosts, ...FALLBACK_POSTS]
    : [...localPosts, ...(posts || [])];

  // Mutations
  const shareMutation = useMutation({
    mutationFn: async () => {
      if (!isSupabaseConfigured) {
        // Demo mode: just add to local state
        if (editingId) {
          setLocalPosts(prev => prev.map(p => p.id === editingId ? { ...p, title, content, image_url: image } : p));
        } else {
          const newPost: Post = {
            id: 'local-' + Date.now(),
            title,
            content,
            image_url: image || undefined,
            user_name: activeUserName,
            user_id: user?.id || null,
            likes: 0,
            dislikes: 0,
            created_at: new Date().toISOString(),
            chat_comments: []
          };
          setLocalPosts(prev => [newPost, ...prev]);
        }
        return;
      }

      if (editingId) {
        const { error } = await supabase.from("chat_posts")
          .update({ title, content, image_url: image, updated_at: new Date().toISOString() })
          .eq("id", editingId);
        if (error) throw error;
      } else {
        const { error } = await supabase.from("chat_posts").insert({
          title,
          content,
          image_url: image,
          user_name: activeUserName,
          user_id: user?.id || null
        });
        if (error) throw error;
      }
    },
    onSuccess: () => {
      if (isSupabaseConfigured) {
        queryClient.invalidateQueries({ queryKey: ["chat_posts"] });
      }
      const isDemo = !isSupabaseConfigured;
      setTitle("");
      setContent("");
      setImage(null);
      setEditingId(null);
      setIsFormOpen(false);
      toast.success(
        editingId
          ? (isDemo ? "Post edited locally (Demo Mode)" : "Post edited successfully!")
          : (isDemo ? "Post published locally (Demo Mode)" : "Post published successfully!")
      );
    },
    onError: (err: any) => toast.error("Error: " + (err.message || "Something went wrong.")),
  });

  const deleteMutation = useMutation({
    mutationFn: async (id: string) => {
      if (!isSupabaseConfigured || id.startsWith('local-')) {
        setLocalPosts(prev => prev.filter(p => p.id !== id));
        return;
      }
      const { error } = await supabase.from("chat_posts").delete().eq("id", id);
      if (error) throw error;
    },
    onSuccess: (_, id) => {
      if (isSupabaseConfigured && !id.startsWith('local-')) {
        queryClient.invalidateQueries({ queryKey: ["chat_posts"] });
      }
      toast.success("Post deleted");
    },
    onError: (err: any) => toast.error("Error: " + err.message),
  });


  const commentMutation = useMutation({
    mutationFn: async ({ postId, text }: { postId: string, text: string }) => {
      if (!isSupabaseConfigured || postId.startsWith('local-')) {
        setLocalPosts(prev => prev.map(p => {
          if (p.id === postId) {
            const newComment: Comment = {
              id: 'local-c-' + Date.now(),
              content: text,
              user_name: activeUserName,
              user_id: null,
              created_at: new Date().toISOString()
            };
            return { ...p, chat_comments: [...p.chat_comments, newComment] };
          }
          return p;
        }));
        return;
      }
      const { error } = await supabase.from("chat_comments").insert({
        post_id: postId,
        content: text,
        user_name: activeUserName,
        user_id: user?.id || null
      });
      if (error) throw error;
    },
    onSuccess: () => {
      if (isSupabaseConfigured) {
        queryClient.invalidateQueries({ queryKey: ["chat_posts"] });
      }
      toast.success("Comment added!");
    },
    onError: (err: any) => toast.error("Error: " + err.message),
  });


  const handleImageChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      if (file.size > 2 * 1024 * 1024) {
        toast.error("Image too large (max 2MB)");
        return;
      }
      const reader = new FileReader();
      reader.onloadend = () => setImage(reader.result as string);
      reader.readAsDataURL(file);
    }
  };

  const handleEdit = (post: Post) => {
    setEditingId(post.id);
    setTitle(post.title);
    setContent(post.content);
    setImage(post.image_url || null);
    setIsFormOpen(true);
    window.scrollTo({ top: 0, behavior: 'smooth' });
  };

  return (
    <div className="min-h-screen bg-[#F0F2F5] selection:bg-royal-emerald selection:text-white">
      <Header />

      <main className="container mx-auto px-4 pt-32 pb-24 relative z-10">
        <div className="max-w-6xl mx-auto">
          {/* Header */}
          <div className="mb-8 flex flex-col md:flex-row md:items-center justify-between gap-6 border-b border-slate-200 pb-8">
            <div>
              <h1 className="text-3xl font-bold text-slate-900 tracking-tight flex items-center gap-3">
                <MessageSquare className="w-8 h-8 text-royal-emerald" />
                {t('chat.forum')}
              </h1>
              <p className="text-slate-500 font-medium mt-1">
                {t('chat.subtitle')}
              </p>
            </div>
            <div className="flex items-center gap-3">
              <div className="hidden sm:flex items-center gap-2 px-4 py-2 bg-white rounded-lg border border-slate-200 text-xs font-bold text-slate-600">
                <Users className="w-4 h-4" />
                1,240 {t('common.online')}
              </div>
              <Button
                onClick={() => setIsFormOpen(!isFormOpen)}
                className={`h-11 px-6 rounded-lg font-bold transition-all ${isFormOpen
                  ? 'bg-blue-200 text-blue-700 hover:bg-blue-300 shadow-sm'
                  : 'bg-blue-600 text-white hover:bg-blue-700 shadow-md ring-1 ring-blue-600/20 focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-offset-2 focus-visible:ring-blue-600'
                  }`}
              >
                {isFormOpen ? t('chat.cancel') : (
                  <>
                    <Plus className="w-4 h-4 mr-2" />
                    {t('chat.new_topic')}
                  </>
                )}
              </Button>
            </div>
          </div>

          <div className="grid grid-cols-1 lg:grid-cols-12 gap-8">
            {/* Feed */}
            <div className="lg:col-span-8 space-y-6">
              {isFormOpen && (
                <Card className="border border-slate-200 shadow-sm rounded-xl overflow-hidden bg-white animate-in slide-in-from-top-2 duration-300">
                  <CardContent className="p-6">
                    <form
                      onSubmit={(e) => { e.preventDefault(); shareMutation.mutate(); }}
                      className="space-y-4"
                    >
                      <div className="flex items-start gap-4">
                        <Avatar className="h-10 w-10 border border-slate-100 shrink-0">
                          <AvatarFallback className="bg-slate-100 text-slate-600 font-bold uppercase">{activeUserName.charAt(0)}</AvatarFallback>
                        </Avatar>
                        <div className="flex-1 space-y-3">
                          <Input
                            placeholder={t('chat.placeholder_title')}
                            value={title}
                            onChange={(e) => setTitle(e.target.value)}
                            className="h-11 border-slate-200 focus:border-royal-emerald focus:ring-1 focus:ring-royal-emerald rounded-lg font-bold text-slate-900"
                          />
                          <Textarea
                            placeholder={t('chat.placeholder_content')}
                            value={content}
                            onChange={(e) => setContent(e.target.value)}
                            className="min-h-[120px] border-slate-200 focus:border-royal-emerald focus:ring-1 focus:ring-royal-emerald rounded-lg font-medium text-slate-600 resize-none"
                          />
                        </div>
                      </div>

                      <div className="flex items-center justify-between pt-4 border-t border-slate-100">
                        <div className="flex gap-2">
                          <Input
                            type="file"
                            accept="image/*"
                            onChange={handleImageChange}
                            className="hidden"
                            id="post-image-upload"
                          />
                          <label
                            htmlFor="post-image-upload"
                            className="flex items-center gap-2 px-3 py-2 rounded-lg hover:bg-slate-100 text-slate-500 cursor-pointer transition-all font-bold text-xs"
                          >
                            <ImageIcon className="w-4 h-4" />
                            {t('chat.media')}
                          </label>
                        </div>
                        <Button
                          disabled={shareMutation.isPending || !title.trim() || !content.trim()}
                          className="h-10 px-6 bg-blue-600 text-white hover:bg-blue-700 rounded-lg font-bold shadow-md transition-all focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-offset-2 focus-visible:ring-blue-600"
                        >
                          {shareMutation.isPending ? t('chat.publishing') : (editingId ? t('common.save') : t('chat.publish'))}
                        </Button>
                      </div>

                      {image && (
                        <div className="relative mt-2 rounded-lg overflow-hidden border border-slate-100 group">
                          <img src={image} alt="Preview" className="w-full h-32 object-cover" />
                          <button
                            type="button"
                            onClick={() => setImage(null)}
                            className="absolute top-2 right-2 p-1 bg-black/50 text-white rounded-full hover:bg-black/70 transition-colors"
                          >
                            <Trash2 className="w-3 h-3" />
                          </button>
                        </div>
                      )}
                    </form>
                  </CardContent>
                </Card>
              )}

              {/* Posts */}
              <div className="space-y-4">
                {isLoading ? (
                  <div className="space-y-4">
                    {[1, 2, 3].map(i => (
                      <div key={i} className="h-40 bg-white border border-slate-200 rounded-xl animate-pulse" />
                    ))}
                  </div>
                ) : displayPosts?.length === 0 ? (
                  <div className="text-center py-20 bg-white border border-slate-200 rounded-xl">
                    <MessageSquare className="w-12 h-12 text-slate-200 mx-auto mb-4" />
                    <h3 className="text-lg font-bold text-slate-800">{t('chat.no_topics')}</h3>
                    <p className="text-slate-500 text-sm mt-1">{t('chat.be_the_first')}</p>
                  </div>
                ) : (
                  displayPosts?.map((post) => (
                    <Card key={post.id} className="border border-slate-200 shadow-sm rounded-xl overflow-hidden bg-white hover:border-royal-emerald/30 transition-all duration-300">
                      <div className="p-5">
                        {/* Post Header */}
                        <div className="flex items-center justify-between mb-4">
                          <div className="flex items-center gap-3">
                            <Avatar className="h-9 w-9 border border-slate-100 shrink-0">
                              <AvatarFallback className="bg-slate-50 text-slate-600 font-bold text-xs uppercase">
                                {post.user_name.charAt(0)}
                              </AvatarFallback>
                            </Avatar>
                            <div>
                              <div className="flex items-center gap-2">
                                <span className="font-bold text-slate-900 text-sm">{post.user_name}</span>
                                <span className="text-[10px] text-slate-400 font-bold flex items-center gap-1 uppercase tracking-wider">
                                  <Calendar className="w-3 h-3" />
                                  {formatDistanceToNow(new Date(post.created_at), { addSuffix: true, locale: dateLocale })}
                                </span>
                              </div>
                            </div>
                          </div>

                          {/* Show edit/delete for: 1) authenticated user's posts, 2) local posts created by current local user */}
                          {((user?.id && user.id === post.user_id) ||
                            (!user?.id && !post.user_id && post.user_name === activeUserName) ||
                            (post.id.startsWith('local-') && post.user_name === activeUserName)) && (
                              <div className="flex gap-1">
                                <Button variant="ghost" size="icon" onClick={() => handleEdit(post)} className="h-8 w-8 rounded-md hover:bg-slate-100 text-slate-400">
                                  <Edit2 className="w-3.5 h-3.5" />
                                </Button>
                                <Button variant="ghost" size="icon" onClick={() => deleteMutation.mutate(post.id)} className="h-8 w-8 rounded-md hover:bg-red-50 text-slate-400 hover:text-red-500">
                                  <Trash2 className="w-3.5 h-3.5" />
                                </Button>
                              </div>
                            )}
                        </div>

                        {/* Post Body */}
                        <div className="flex flex-col md:flex-row gap-6">
                          <div className="flex-1">
                            <h3 className="text-xl font-bold text-slate-900 mb-2 leading-tight">{post.title}</h3>
                            <p className="text-slate-600 font-medium text-sm leading-relaxed line-clamp-3 mb-4">{post.content}</p>
                          </div>
                          {post.image_url && (
                            <div className="w-full md:w-32 h-24 shrink-0 rounded-lg overflow-hidden border border-slate-100">
                              <img src={post.image_url} alt={post.title} className="w-full h-full object-cover" />
                            </div>
                          )}
                        </div>

                        {/* Reactions */}
                        <div className="flex items-center gap-4 pt-4 border-t border-slate-50">
                          <button
                            onClick={() => handleReaction(post.id, 'like')}
                            className={`flex items-center gap-1.5 text-xs font-bold transition-colors
                              ${localReactions[post.id] === 'like' ? 'text-royal-emerald bg-royal-emerald/10' : 'text-slate-400 hover:text-royal-emerald hover:bg-slate-50'}
                              rounded-md px-2 py-1`}
                          >
                            <Heart className={`w-4 h-4 ${localReactions[post.id] === 'like' ? 'fill-current' : ''}`} />
                            {post.likes + (localReactions[post.id] === 'like' ? 1 : 0)}
                          </button>

                          <button
                            onClick={() => handleReaction(post.id, 'dislike')}
                            className={`flex items-center gap-1.5 text-xs font-bold transition-colors
                              ${localReactions[post.id] === 'dislike' ? 'text-red-500 bg-red-500/10' : 'text-slate-400 hover:text-red-500 hover:bg-slate-50'}
                              rounded-md px-2 py-1`}
                          >
                            <ThumbsDown className="w-4 h-4" />
                            {post.dislikes + (localReactions[post.id] === 'dislike' ? 1 : 0)}
                          </button>

                          <button
                            onClick={() => {
                              const commentSection = document.getElementById(`comments-${post.id}`);
                              if (commentSection) {
                                commentSection.classList.toggle('hidden');
                              }
                            }}
                            className="flex items-center gap-1.5 text-xs font-bold text-slate-400 hover:text-blue-600 hover:bg-slate-50 rounded-md px-2 py-1 transition-colors"
                          >
                            <MessageSquare className="w-4 h-4" />
                            {post.chat_comments?.length || 0}
                          </button>
                        </div>

                        {/* Comments Section */}
                        <div id={`comments-${post.id}`} className="hidden mt-4 pt-4 border-t border-slate-100 space-y-3">
                          {/* Existing Comments */}
                          {post.chat_comments && post.chat_comments.length > 0 && (
                            <div className="space-y-2 mb-3">
                              {post.chat_comments.map((comment) => (
                                <div key={comment.id} className="flex gap-2 bg-slate-50 rounded-lg p-3">
                                  <Avatar className="h-7 w-7 border border-slate-200 shrink-0">
                                    <AvatarFallback className="bg-white text-slate-600 font-bold text-xs uppercase">
                                      {comment.user_name.charAt(0)}
                                    </AvatarFallback>
                                  </Avatar>
                                  <div className="flex-1 min-w-0">
                                    <div className="flex items-center gap-2 mb-1">
                                      <span className="font-bold text-slate-900 text-xs">{comment.user_name}</span>
                                      <span className="text-[9px] text-slate-400 font-bold uppercase">
                                        {formatDistanceToNow(new Date(comment.created_at), { addSuffix: true, locale: dateLocale })}
                                      </span>
                                    </div>
                                    <p className="text-sm text-slate-600 font-medium break-words">{comment.content}</p>
                                  </div>
                                </div>
                              ))}
                            </div>
                          )}

                          {/* Add Comment Form */}
                          <form
                            onSubmit={(e) => {
                              e.preventDefault();
                              const input = e.currentTarget.elements.namedItem('comment-input') as HTMLInputElement;
                              if (input.value.trim()) {
                                commentMutation.mutate({ postId: post.id, text: input.value });
                                input.value = '';
                              }
                            }}
                            className="flex gap-2"
                          >
                            <Avatar className="h-7 w-7 border border-slate-200 shrink-0">
                              <AvatarFallback className="bg-slate-100 text-slate-600 font-bold text-xs uppercase">
                                {activeUserName.charAt(0)}
                              </AvatarFallback>
                            </Avatar>
                            <div className="flex-1 flex gap-2">
                              <Input
                                name="comment-input"
                                placeholder={t('chat.add_comment')}
                                className="h-9 border-slate-200 focus:border-royal-emerald focus:ring-1 focus:ring-royal-emerald rounded-lg text-sm"
                              />
                              <Button
                                type="submit"
                                size="sm"
                                className="h-9 px-4 bg-blue-600 text-white hover:bg-blue-700 rounded-lg font-bold shadow-sm"
                              >
                                <Send className="w-3.5 h-3.5" />
                              </Button>
                            </div>
                          </form>
                        </div>

                      </div>
                    </Card>
                  ))
                )}
              </div>
            </div>

            {/* Sidebar */}
            <div className="lg:col-span-4 space-y-6">
              <Card className="border border-slate-200 shadow-sm rounded-xl bg-white overflow-hidden">
                <div className="bg-slate-900 p-4 flex items-center gap-3">
                  <Avatar className="h-10 w-10 border-2 border-slate-800">
                    <AvatarFallback className="bg-royal-emerald text-white font-bold">{activeUserName.charAt(0)}</AvatarFallback>
                  </Avatar>
                  <div>
                    <p className="text-sm font-bold text-white">{activeUserName}</p>
                    <p className="text-[10px] text-slate-400 font-bold uppercase tracking-widest">{t('common.online')}</p>
                  </div>
                </div>
                <CardContent className="p-4 space-y-2">
                  <div className="flex justify-between items-center text-xs p-2.5 bg-slate-50 rounded-lg">
                    <span className="text-slate-500 font-bold uppercase tracking-tighter">{t('chat.my_posts')}</span>
                    <span className="font-bold text-slate-900">{displayPosts?.filter(p => p.user_id === user?.id).length || 0}</span>
                  </div>
                  <div className="flex justify-between items-center text-xs p-2.5 bg-slate-50 rounded-lg">
                    <span className="text-slate-500 font-bold uppercase tracking-tighter">{t('chat.score_impact')}</span>
                    <span className="font-bold text-royal-emerald">
                      {(displayPosts?.filter(p => p.user_id === user?.id).reduce((acc, p) => acc + (p.likes || 0), 0) || 0) * 10} pts
                    </span>
                  </div>

                </CardContent>
              </Card>
            </div>
          </div>
        </div>
      </main>
    </div>
  );
};

export default Chat;

import { Header } from '@/components/Header';
import { GroupStandings } from '@/components/GroupStandings';
import { useQuery } from '@tanstack/react-query';
import { supabase } from '@/integrations/supabase/client';
import { Loader2, Shield } from 'lucide-react';
import { Button } from '@/components/ui/button';
import { useTranslation } from 'react-i18next';

import { TeamStats } from '@/components/TeamState';
import { GeneralStats } from '@/components/GeneralStats';
import { FALLBACK_TEAMS } from '@/data/fallbackData';


export default function Groups() {
  const { t } = useTranslation();
  const { data: teams, isLoading, error: queryError, refetch } = useQuery({
    queryKey: ['teams'],
    queryFn: async () => {
      console.log('Fetching teams from Supabase...');
      try {
        const { data, error } = await supabase.from('teams').select('*').order('group_name').order('name');
        if (error) {
          console.error('Supabase error fetching teams:', error);
          throw error;
        }
        console.log('Teams fetched successfully:', data?.length, 'teams found.');
        return data;
      } catch (err) {
        console.error('Unexpected error in queryFn:', err);
        throw err;
      }
    },
    retry: 1, // Don't retry too many times
  });

  // Use fallback data if there's an error or no data returned
  const displayTeams = queryError || (!isLoading && (!teams || teams.length === 0)) ? FALLBACK_TEAMS : teams;

  const groupedTeams = displayTeams?.reduce((acc, team: any) => {
    if (!acc[team.group_name]) acc[team.group_name] = [];
    acc[team.group_name].push(team);
    return acc;
  }, {} as Record<string, any[]>);


  return (
    <div className="min-h-screen bg-transparent">
      <Header />
      <main className="container mx-auto px-4 py-12">
        <div className="text-center mb-10 mt-20">
          <h1 className="font-display text-5xl text-white mb-2">{t('groups.title')}</h1>
          <p className="text-muted-foreground  text-white">{t('groups.subtitle')}</p>
        </div>

        {isLoading ? (
          <div className="flex flex-col items-center justify-center py-20 gap-4">
            <Loader2 className="w-8 h-8 animate-spin text-primary" />
            <p className="text-sm text-muted-foreground animate-pulse">{t('groups.loading')}</p>
          </div>
        ) : (
          <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
            {groupedTeams && Object.entries(groupedTeams).map(([groupName, groupTeams]) => (
              <GroupStandings key={groupName} groupName={groupName} teams={groupTeams || []} />
            ))}
          </div>
        )}

        <br />
        <hr />
        <br />
        <h1 className="text-center font-display text-5xl text-white mb-2">{t('groups.overview')}</h1>
        <GeneralStats />
      </main>
    </div>

  );
}

import { useState, useEffect } from "react";
import { useNavigate } from "react-router-dom";
import { useAuth } from "@/lib/auth";
import { supabase } from "@/integrations/supabase/client";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Card, CardContent } from "@/components/ui/card";
import { Avatar, AvatarImage, AvatarFallback } from "@/components/ui/avatar";
import {
    Trophy, Camera, Loader2, Check,
    ChevronRight, Sparkles, Star, Shield
} from "lucide-react";
import { toast } from "sonner";
import { FALLBACK_TEAMS } from "@/data/fallbackData";
import { isSupabaseConfigured } from "@/integrations/supabase/client";
import { useTranslation } from "react-i18next";


export default function ProfileSetup() {
    const { t } = useTranslation();
    const { user, updateProfile } = useAuth();
    const navigate = useNavigate();
    const [loading, setLoading] = useState(false);
    const [fullName, setFullName] = useState("");
    const [favoriteTeam, setFavoriteTeam] = useState("");
    const [avatarUrl, setAvatarUrl] = useState<string | null>(null);
    const [previewUrl, setPreviewUrl] = useState<string | null>(null);

    useEffect(() => {
        if (!user) {
            navigate("/auth");
        } else if (user.user_metadata) {
            setFullName(user.user_metadata.full_name || "");
            setFavoriteTeam(user.user_metadata.favorite_team || "");
            setPreviewUrl(user.user_metadata.avatar_url || null);
        }
    }, [user, navigate]);

    const handleImageChange = (e: React.ChangeEvent<HTMLInputElement>) => {
        const file = e.target.files?.[0];
        if (file) {
            if (file.size > 2 * 1024 * 1024) {
                toast.error("Image too large (max 2MB)");
                return;
            }
            const reader = new FileReader();
            reader.onloadend = () => {
                setPreviewUrl(reader.result as string);
                setAvatarUrl(reader.result as string); // Using base64 for now to avoid storage complexity
            };
            reader.readAsDataURL(file);
        }
    };

    const handleSubmit = async (e: React.FormEvent) => {
        e.preventDefault();
        if (!user) return;

        setLoading(true);
        try {
            const { error } = await updateProfile({
                full_name: fullName,
                avatar_url: avatarUrl || undefined,
                favorite_team: favoriteTeam
            });

            if (error) throw error;

            toast.success(t('auth.security_note'), { // Using security note as success for now or translation
                icon: <Sparkles className="w-4 h-4 text-saffron" />
            });
            navigate("/");
        } catch (err: any) {
            toast.error("Error updating profile: " + err.message);
        } finally {
            setLoading(false);
        }
    };


    return (
        <div className="min-h-screen bg-gradient-royal overflow-hidden relative flex items-center justify-center p-4 py-20">
            {/* Background Ornaments from Auth page */}
            <div className="absolute inset-0 zellige-grid opacity-[0.1] animate-float pointer-events-none" />
            <div className="absolute -top-24 -left-24 w-96 h-96 moorish-arch bg-gradient-to-br from-saffron/10 to-transparent -rotate-45" />
            <div className="absolute -bottom-24 -right-24 w-96 h-96 star-8-clip bg-gradient-to-tl from-star-red/10 to-transparent rotate-45" />

            <div className="w-full max-w-xl relative z-10 transition-all duration-700 animate-in fade-in zoom-in-95">
                <div className="glass-zellige rounded-[2.5rem] p-8 md:p-12 shadow-2xl relative overflow-hidden backdrop-blur-xl border border-white/20">

                    <div className="text-center mb-10">
                        <h1 className="font-royal text-4xl text-royal-emerald mb-4 uppercase tracking-tighter">
                            {t('profile_setup.title')} <span className="text-star-red">{t('profile_setup.subtitle')}</span>
                        </h1>
                        <p className="text-royal-emerald/60 font-black uppercase tracking-[0.2em] text-[10px] bg-white/10 px-4 py-1.5 rounded-full inline-block">
                            {t('profile_setup.welcome')}
                        </p>
                    </div>

                    <form onSubmit={handleSubmit} className="space-y-8">
                        {/* Avatar Selection */}
                        <div className="flex flex-col items-center gap-4">
                            <div className="relative group">
                                <div className="absolute inset-0 bg-gradient-to-br from-saffron via-star-red to-royal-emerald blur-xl opacity-20 group-hover:opacity-40 transition-opacity rounded-full" />
                                <Avatar className="w-32 h-32 border-4 border-white/30 shadow-2xl relative ring-4 ring-royal-emerald/5">
                                    <AvatarImage src={previewUrl || ""} className="object-cover" />
                                    <AvatarFallback className="bg-gradient-to-br from-slate-100 to-slate-200 text-royal-emerald font-royal text-3xl">
                                        {fullName.charAt(0) || <Trophy className="w-10 h-10 opacity-20" />}
                                    </AvatarFallback>
                                </Avatar>
                                <label
                                    htmlFor="avatar-upload"
                                    className="absolute bottom-0 right-0 p-3 bg-saffron text-royal-emerald rounded-2xl shadow-lg cursor-pointer hover:scale-110 active:scale-95 transition-all duration-300 ring-4 ring-white"
                                >
                                    <Camera className="w-5 h-5" />
                                    <input
                                        type="file"
                                        id="avatar-upload"
                                        className="hidden"
                                        accept="image/*"
                                        onChange={handleImageChange}
                                    />
                                </label>
                            </div>
                            <p className="text-[10px] font-black text-royal-emerald/40 uppercase tracking-widest">
                                {t('chat.media')}
                            </p>
                        </div>

                        <div className="space-y-6">
                            {/* Full Name */}
                            <div className="space-y-2">
                                <Label className="font-royal text-royal-emerald/80 uppercase tracking-widest text-[10px] ml-2 flex items-center gap-1">
                                    <span className="w-1 h-1 bg-saffron rounded-full" />
                                    {t('profile_setup.label_name')}
                                </Label>
                                <Input
                                    value={fullName}
                                    onChange={(e) => setFullName(e.target.value)}
                                    placeholder={t('profile_setup.placeholder_name')}
                                    required
                                    className="h-14 bg-white/40 border-royal-emerald/10 rounded-2xl font-royal text-royal-emerald focus:ring-2 focus:ring-saffron/30 transition-all placeholder:text-royal-emerald/20 text-lg px-6 shadow-inner"
                                />
                            </div>

                            {/* Favorite Team */}
                            <div className="space-y-2">
                                <Label className="font-royal text-royal-emerald/80 uppercase tracking-widest text-[10px] ml-2 flex items-center gap-1">
                                    <span className="w-1 h-1 bg-saffron rounded-full" />
                                    {t('profile_setup.label_team')}
                                </Label>
                                <div className="grid grid-cols-2 sm:grid-cols-4 gap-3 max-h-48 overflow-y-auto pr-2 custom-scrollbar">
                                    {FALLBACK_TEAMS.map((team) => (
                                        <button
                                            key={team.id}
                                            type="button"
                                            onClick={() => setFavoriteTeam(team.name)}
                                            className={`relative p-3 rounded-2xl border transition-all duration-300 group flex flex-col items-center gap-2 ${favoriteTeam === team.name
                                                ? 'bg-royal-emerald border-saffron shadow-lg scale-105'
                                                : 'bg-white/40 border-royal-emerald/5 hover:border-royal-emerald/20 hover:bg-white/60'
                                                }`}
                                        >
                                            <img src={team.flag_url} alt={team.name} className="w-8 h-6 object-cover rounded-sm shadow-sm" />
                                            <span className={`text-[9px] font-black uppercase tracking-tighter text-center line-clamp-1 ${favoriteTeam === team.name ? 'text-white' : 'text-royal-emerald/70'
                                                }`}>
                                                {team.name}
                                            </span>
                                            {favoriteTeam === team.name && (
                                                <div className="absolute -top-1 -right-1 bg-saffron text-royal-emerald rounded-full p-0.5 shadow-sm">
                                                    <Check className="w-2.5 h-2.5" />
                                                </div>
                                            )}
                                        </button>
                                    ))}
                                </div>
                            </div>
                        </div>

                        <Button
                            type="submit"
                            disabled={loading || !fullName || !favoriteTeam}
                            className="btn-royal w-full h-16 text-md mt-6 shadow-2xl shadow-royal-emerald/30 group relative overflow-hidden flex items-center justify-center gap-3 rounded-2xl"
                        >
                            <div className="absolute inset-0 bg-gradient-to-r from-transparent via-white/20 to-transparent -translate-x-full group-hover:translate-x-full transition-transform duration-1000" />
                            {loading ? (
                                <Loader2 className="w-6 h-6 animate-spin" />
                            ) : (
                                <>
                                    {t('profile_setup.btn_join')}
                                    <ChevronRight className="w-5 h-5 group-hover:translate-x-1 transition-transform" />
                                </>
                            )}
                        </Button>
                    </form>

                    <p className="text-[9px] text-royal-emerald/30 mt-8 text-center font-medium uppercase tracking-[0.3em]">
                        {t('auth.security_note')}
                    </p>
                </div>
            </div>
        </div>
    );
}

